"use client";
import { useEffect,useMemo,useState } from "react";
import type { V8StayOffer } from "@/lib/decision/v8-types";
import type { StayReviewIntelligenceV39 } from "@/lib/data/stay-review-intelligence-v39";
import styles from "./v39-stay-review-hero.module.css";

type Lang="el"|"en";
type Props={offer:V8StayOffer;slug:string;destination:string;destinationEn:string;lang:Lang};
const say=(l:Lang,el:string,en:string)=>l==="el"?el:en;
const money=(o:V8StayOffer,l:Lang)=>o.price!=null&&o.price>0?`${o.price.toLocaleString(l==="el"?"el-GR":"en-GB",{maximumFractionDigits:2})} ${o.currency||"EUR"}`:say(l,"Τιμή στον πάροχο","Price at provider");
export function V39StayReviewHero({offer,slug,destination,destinationEn,lang}:Props){const[intel,setIntel]=useState<StayReviewIntelligenceV39|null|undefined>(undefined),name=lang==="en"?destinationEn:destination;useEffect(()=>{let dead=false;fetch("/api/escape/stay-reviews",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({propertyName:offer.propertyName,sourceProductId:offer.sourceProductId,destinationSlug:slug,destinationName:name,latitude:offer.latitude,longitude:offer.longitude,language:lang})}).then(r=>r.ok?r.json():null).then(p=>{if(!dead)setIntel(p?.result??null)}).catch(()=>{if(!dead)setIntel(null)});return()=>{dead=true}},[offer.sourceProductId,slug,name,lang]);const images=useMemo(()=>{const out=new Set<string>();for(const x of[offer.imageUrl,offer.thumbUrl])if(typeof x==="string"&&x.startsWith("https://"))out.add(x);const raw=offer.raw??{};for(const[k,v]of Object.entries(raw))if(/image|photo|gallery|thumb/i.test(k)){if(typeof v==="string")for(const token of v.split(/[|,;\s]+/))if(token.startsWith("https://"))out.add(token);if(Array.isArray(v))for(const token of v)if(typeof token==="string"&&token.startsWith("https://"))out.add(token)}return[...out].slice(0,4)},[offer]);const main=images[0]??null;return <section className={styles.hero}>{main?<img className={styles.bg} src={main} alt=""/>:null}<div className={styles.shade}/><div className={styles.copy}><a href={`/escape/${encodeURIComponent(slug)}`} className={styles.back}>← {say(lang,"πίσω στον χάρτη","back to map")}</a><span>{say(lang,"SELECTED STAY · REVIEW INTELLIGENCE","SELECTED STAY · REVIEW INTELLIGENCE")}</span><h1>{offer.propertyName}</h1><p>{offer.city||offer.address||name}</p><div className={styles.price}>{money(offer,lang)}</div><div className={styles.ratings}>{intel===undefined?<b>{say(lang,"Σκανάρω verified ratings…","Scanning verified ratings…")}</b>:intel?.ratings.length?intel.ratings.map(r=><b key={r.provider}>{r.provider}: {r.rating.toFixed(1)}/{r.scale}{r.reviewCount!=null?` · ${r.reviewCount.toLocaleString()}`:""}</b>):<b>{say(lang,"Δεν βρέθηκε verified external rating για αυτό το property match.","No verified external rating was found for this exact property match.")}</b>}</div>{intel?.summary?<p className={styles.summary}>{intel.summary}</p>:null}<div className={styles.themes}>{intel?.positives.map(x=><i key={`p-${x}`}>✓ {x}</i>)}{intel?.watchouts.map(x=><i key={`w-${x}`} className={styles.watch}>△ {x}</i>)}</div><div className={styles.truth}><strong>{say(lang,"Disclosure","Disclosure")}</strong><p>{intel?.disclosure||say(lang,"Τα ratings εμφανίζονται μόνο όταν επιβεβαιωθούν από τον ονομαζόμενο provider. Η τελική τιμή και διαθεσιμότητα επιβεβαιώνονται αργότερα στον συνεργάτη.","Ratings appear only when verified by the named provider. Final price and availability are confirmed later with the partner.")}</p></div><a href="#escape-builder" className={styles.cta}>{say(lang,"Χτίσε το πλήρες 360° itinerary ↓","Build the full 360° itinerary ↓")}</a></div><div className={styles.gallery}>{images.slice(1).map((url,i)=><img key={url} src={url} alt={`${offer.propertyName} ${i+2}`} loading="lazy"/>)}</div></section>}

@keyframes ken{0%{transform:scale(1.02)}100%{transform:scale(1.075)}}
@keyframes rise{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}
@keyframes pulse{0%,100%{opacity:.34;transform:scale(.86)}50%{opacity:1;transform:scale(1.08)}}
@keyframes drift{0%,100%{transform:translate3d(-4%,0,0) scale(1)}50%{transform:translate3d(4%,2%,0) scale(1.08)}}

.shell{--ink:#02090d;--panel:rgba(4,17,23,.82);--panel2:rgba(8,27,35,.76);--line:rgba(124,226,232,.15);--lineStrong:rgba(92,240,239,.4);--muted:rgba(224,239,242,.67);--cyan:#54f2ef;--cyan2:#17bfcb;--ice:#dffefe;--white:#f5fbfc;position:relative;min-height:100svh;overflow:hidden;background:#02090d;color:var(--white);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;isolation:isolate}
.backdrop{position:absolute;inset:-4%;z-index:0;background-image:var(--hero);background-size:cover;background-position:center 42%;filter:saturate(.82) contrast(1.08) brightness(.42);animation:ken 24s ease-in-out infinite alternate;transition:background-image .65s ease}
.aurora{position:absolute;z-index:1;inset:-16% -12% 12% 22%;pointer-events:none;opacity:.36;filter:blur(62px);background:radial-gradient(ellipse at 30% 25%,rgba(51,244,222,.47),transparent 36%),radial-gradient(ellipse at 70% 18%,rgba(37,152,190,.42),transparent 31%),radial-gradient(ellipse at 62% 78%,rgba(64,102,192,.24),transparent 34%);animation:drift 17s ease-in-out infinite}
.vignette{position:absolute;inset:0;z-index:2;background:linear-gradient(90deg,rgba(1,7,10,.97) 0%,rgba(2,10,14,.91) 40%,rgba(1,8,12,.56) 70%,rgba(1,7,10,.8) 100%),linear-gradient(0deg,rgba(1,7,10,.96),rgba(1,7,10,.14) 64%)}
.grain{position:absolute;inset:0;z-index:2;opacity:.035;pointer-events:none;background-image:radial-gradient(rgba(255,255,255,.8) .4px,transparent .4px);background-size:4px 4px}

.nav{position:relative;z-index:10;height:74px;padding:0 clamp(18px,4vw,64px);display:grid;grid-template-columns:minmax(210px,1fr) auto minmax(210px,1fr);align-items:center;border-bottom:1px solid rgba(255,255,255,.075);background:rgba(2,11,15,.58);backdrop-filter:blur(22px) saturate(125%)}
.brand{display:flex;gap:11px;align-items:center;width:max-content;text-decoration:none;color:#fff}.brandMark{width:37px;height:37px;display:grid;place-items:center;border:1px solid rgba(84,242,239,.48);border-radius:50%;background:rgba(20,70,75,.24);color:var(--cyan);box-shadow:inset 0 0 18px rgba(84,242,239,.08),0 0 24px rgba(34,221,221,.06)}.brand div{display:flex;flex-direction:column}.brand b{font-size:20px;line-height:1;font-weight:850;letter-spacing:-.035em}.brand small{margin-top:5px;font-size:7px;letter-spacing:.16em;text-transform:uppercase;color:rgba(219,244,246,.45)}
.navLinks{display:flex;align-items:center;gap:30px}.navLinks a{position:relative;color:rgba(235,248,249,.68);font-size:11px;font-weight:650;text-decoration:none;transition:.18s ease}.navLinks a:after{content:"";position:absolute;left:0;right:100%;bottom:-9px;height:1px;background:var(--cyan);transition:.2s ease}.navLinks a:hover{color:#fff}.navLinks a:hover:after{right:0}
.navActions{justify-self:end;display:flex;align-items:center;gap:15px}.langSwitch{display:grid;place-items:center;min-width:42px;height:32px;border:1px solid rgba(255,255,255,.11);border-radius:999px;color:rgba(240,250,251,.68);font-size:10px;font-weight:800;text-decoration:none;background:rgba(255,255,255,.035)}.status{display:flex;align-items:center;gap:8px;padding:8px 12px;border:1px solid rgba(84,242,239,.14);border-radius:999px;background:rgba(7,34,39,.5);font-size:9px;font-weight:780;text-transform:uppercase;letter-spacing:.08em;color:rgba(230,249,249,.74)}.status i,.liveBadge i{width:6px;height:6px;border-radius:50%;background:var(--cyan);box-shadow:0 0 13px rgba(84,242,239,.9)}

.stage{position:relative;z-index:4;min-height:calc(100svh - 74px);display:flex;align-items:center;padding:42px clamp(20px,5vw,78px) 60px}
.landingGrid{width:min(1390px,100%);margin:0 auto;display:grid;grid-template-columns:minmax(0,1.1fr) minmax(350px,.78fr);gap:clamp(32px,5vw,78px);align-items:center;animation:rise .42s ease both}.heroPanel,.questionPanel,.setupPanel,.thinking,.results{width:100%;animation:rise .38s ease both}.questionPanel,.setupPanel,.thinking{max-width:1080px;margin:0 auto}.results{max-width:1320px;margin:0 auto}
.releaseTag,.eyebrow{display:flex;align-items:center;gap:9px;margin:0 0 16px;font-size:9px;font-weight:850;letter-spacing:.18em;text-transform:uppercase;color:rgba(101,244,241,.75)}.releaseTag i{width:28px;height:1px;background:var(--cyan);box-shadow:0 0 10px rgba(84,242,239,.5)}
.heroPanel h1,.questionPanel h1,.setupPanel h1,.thinking h1,.resultsTop h1{margin:0;max-width:920px;font-family:Inter,ui-sans-serif,system-ui,sans-serif;font-weight:850;letter-spacing:-.058em;line-height:.97;text-wrap:balance;text-shadow:0 14px 46px rgba(0,0,0,.3)}
.heroPanel h1{font-size:clamp(48px,6vw,88px)}.questionPanel h1,.setupPanel h1,.thinking h1{font-size:clamp(42px,5vw,70px)}.resultsTop h1{font-size:clamp(38px,4vw,58px)}
.lead{max-width:730px;margin:19px 0 26px;font-size:clamp(15px,1.3vw,18px);line-height:1.62;color:var(--muted)}

.composer{width:min(850px,100%);display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-areas:"head button" "input button";gap:4px 14px;padding:14px 14px 14px 18px;border:1px solid rgba(100,236,235,.22);border-radius:20px;background:linear-gradient(140deg,rgba(7,28,36,.93),rgba(3,16,22,.88));backdrop-filter:blur(26px) saturate(135%);box-shadow:0 26px 90px rgba(0,0,0,.38),inset 0 1px rgba(255,255,255,.04)}
.composerHead{grid-area:head;display:flex;align-items:center;gap:10px;padding:3px 5px 0}.composerHead>span{display:grid;place-items:center;width:28px;height:28px;border-radius:8px;background:rgba(84,242,239,.1);color:var(--cyan)}.composerHead div{display:flex;flex-direction:column;gap:2px}.composerHead b{font-size:11px;letter-spacing:.01em}.composerHead small{font-size:9px;color:rgba(220,239,241,.45)}
.composer textarea{grid-area:input;min-height:76px;resize:none;border:0;outline:none;background:transparent;color:#fff;padding:7px 5px 3px;font:500 14px/1.55 inherit}.composer textarea::placeholder{color:rgba(229,244,245,.34)}.composer button{grid-area:button;align-self:stretch;min-width:170px;display:flex;align-items:center;justify-content:space-between;gap:14px;border:1px solid rgba(130,255,253,.54);border-radius:14px;background:var(--cyan);color:#001014;padding:12px 13px 12px 16px;font-size:11px;font-weight:900;cursor:pointer;box-shadow:0 10px 36px rgba(36,226,226,.16);transition:.18s ease}.composer button b{display:grid;place-items:center;width:27px;height:27px;border-radius:9px;background:rgba(0,20,23,.12);font-size:14px}.composer button:hover:not(:disabled){transform:translateY(-2px);background:#8cfbf8}.composer button:disabled{opacity:.48;cursor:wait}
.ideaRow{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.ideaRow button{display:flex;align-items:center;gap:9px;border:1px solid rgba(255,255,255,.09);border-radius:999px;background:rgba(3,19,25,.48);color:rgba(234,247,248,.64);padding:8px 11px;font-size:9px;font-weight:650;cursor:pointer;backdrop-filter:blur(12px);transition:.16s ease}.ideaRow button span{color:var(--cyan)}.ideaRow button:hover{border-color:rgba(84,242,239,.3);color:#fff;background:rgba(10,39,45,.64)}
.trust{display:flex;gap:18px;flex-wrap:wrap;margin-top:18px;font-size:8px;font-weight:750;text-transform:uppercase;letter-spacing:.13em;color:rgba(220,240,241,.43)}.trust span:before{content:"";display:inline-block;width:4px;height:4px;border-radius:50%;background:var(--cyan);margin-right:7px;vertical-align:2px}

.plannerCard{position:relative;overflow:hidden;min-height:465px;padding:23px;border:1px solid rgba(84,242,239,.21);border-radius:24px;background:linear-gradient(155deg,rgba(6,29,38,.88),rgba(2,15,21,.91));backdrop-filter:blur(28px) saturate(140%);box-shadow:0 32px 100px rgba(0,0,0,.39),inset 0 1px rgba(255,255,255,.045)}.plannerCard:before{content:"";position:absolute;width:270px;height:270px;right:-130px;top:-120px;border-radius:50%;background:rgba(55,235,224,.12);filter:blur(45px);pointer-events:none}.plannerTop{position:relative;z-index:1;display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.plannerTop small{font-size:8px;font-weight:850;letter-spacing:.16em;color:rgba(84,242,239,.72)}.plannerTop h2{max-width:390px;margin:8px 0 0;font-size:clamp(21px,2vw,31px);line-height:1.08;letter-spacing:-.04em}.liveBadge{display:flex;align-items:center;gap:6px;padding:7px 9px;border:1px solid rgba(84,242,239,.17);border-radius:999px;background:rgba(84,242,239,.055);font-size:8px;font-weight:900;letter-spacing:.1em;color:rgba(211,255,253,.75)}
.mediaFan{position:relative;height:188px;margin:30px 2px 26px}.mediaTile{position:absolute;top:8px;width:42%;height:164px;border:1px solid rgba(255,255,255,.15);border-radius:16px;background:linear-gradient(145deg,#12343f,#06171d);background-size:cover;background-position:center;box-shadow:0 24px 50px rgba(0,0,0,.33);overflow:hidden}.mediaTile:after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,rgba(1,9,12,.78),transparent 58%)}.mediaTile:nth-child(1){left:1%;transform:rotate(-6deg)}.mediaTile:nth-child(2){left:29%;top:0;z-index:2;transform:rotate(1.8deg)}.mediaTile:nth-child(3){right:1%;transform:rotate(7deg)}.mediaTile span{position:absolute;z-index:3;left:11px;bottom:10px;font-size:8px;text-transform:uppercase;letter-spacing:.12em;font-weight:850;color:#fff}
.reasonFlow{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;gap:9px;align-items:center;padding:13px;border:1px solid rgba(255,255,255,.075);border-radius:16px;background:rgba(0,9,13,.32)}.reasonFlow>div{display:flex;min-width:0;flex-direction:column}.reasonFlow>div>span{font-size:8px;color:rgba(84,242,239,.65)}.reasonFlow b{margin-top:3px;font-size:10px}.reasonFlow small{margin-top:2px;font-size:7px;white-space:nowrap;color:rgba(224,242,243,.42)}.reasonFlow>i{font-style:normal;color:rgba(84,242,239,.35)}
.plannerFoot{display:flex;gap:11px;align-items:flex-start;margin-top:16px;padding-top:15px;border-top:1px solid rgba(255,255,255,.065)}.plannerFoot>span{color:var(--cyan)}.plannerFoot p{margin:0;font-size:9px;line-height:1.5;color:rgba(224,241,242,.49)}

.capabilities{grid-column:1/-1;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin-top:-2px;border:1px solid rgba(255,255,255,.07);border-radius:18px;background:rgba(3,17,22,.62);backdrop-filter:blur(18px);overflow:hidden}.capabilities>div{display:flex;gap:12px;align-items:center;padding:15px 18px;border-right:1px solid rgba(255,255,255,.065)}.capabilities>div:last-child{border-right:0}.capabilities>div>span{display:grid;place-items:center;width:30px;height:30px;flex:0 0 30px;border-radius:10px;background:rgba(84,242,239,.07);color:var(--cyan);font-size:14px}.capabilities p{display:flex;flex-direction:column;margin:0}.capabilities b{font-size:9px}.capabilities small{margin-top:3px;font-size:7.5px;color:rgba(221,240,241,.4)}

.questionPanel,.setupPanel,.thinking{padding:clamp(24px,4vw,48px);border:1px solid rgba(84,242,239,.15);border-radius:26px;background:linear-gradient(145deg,rgba(4,23,30,.84),rgba(2,14,19,.9));backdrop-filter:blur(28px);box-shadow:0 34px 110px rgba(0,0,0,.33)}
.error{margin-top:13px;padding:11px 14px;max-width:860px;border:1px solid rgba(255,116,116,.25);border-radius:12px;background:rgba(95,20,24,.34);color:#ffdede;font-size:12px}
.agentCue{display:flex;gap:13px;max-width:850px;margin-bottom:25px;padding:14px 15px;border:1px solid rgba(84,242,239,.14);border-left:2px solid var(--cyan);border-radius:0 14px 14px 0;background:rgba(7,35,42,.4)}.agentCue>span{width:31px;height:31px;display:grid;place-items:center;border-radius:9px;background:rgba(84,242,239,.1);color:var(--cyan)}.agentCue small{font-size:8px;letter-spacing:.13em;text-transform:uppercase;color:rgba(84,242,239,.65)}.agentCue p{margin:4px 0 0;color:rgba(236,248,249,.77);line-height:1.5;font-size:12px}
.choiceGrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:28px;max-width:930px}.choiceGrid button{min-height:92px;display:flex;justify-content:space-between;align-items:flex-end;text-align:left;border:1px solid rgba(255,255,255,.1);border-radius:16px;background:rgba(4,23,30,.64);color:#fff;padding:16px;font-size:12px;font-weight:750;cursor:pointer;transition:.18s ease}.choiceGrid button span{color:var(--cyan);opacity:.6}.choiceGrid button:hover{transform:translateY(-3px);border-color:rgba(84,242,239,.35);background:rgba(10,42,49,.74)}.skip{margin-top:14px;border:0;background:transparent;color:rgba(230,245,246,.5);font-size:10px;text-decoration:underline;text-underline-offset:4px;cursor:pointer}
.panelKicker{display:flex;gap:11px;align-items:center;margin-bottom:19px}.panelKicker>span{display:grid;place-items:center;width:32px;height:32px;border-radius:10px;background:rgba(84,242,239,.1);color:var(--cyan)}.panelKicker p{display:flex;flex-direction:column;margin:0}.panelKicker b{font-size:8px;letter-spacing:.16em;color:var(--cyan)}.panelKicker small{margin-top:3px;font-size:9px;color:rgba(224,241,242,.45)}
.setupSummary{max-width:830px;color:rgba(235,247,248,.65);line-height:1.6;font-size:13px}.tripGrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:25px}.tripGrid label{display:flex;flex-direction:column;gap:8px;padding:13px;border:1px solid rgba(255,255,255,.095);border-radius:15px;background:rgba(1,12,17,.53)}.tripGrid label>span{font-size:8px;font-weight:800;text-transform:uppercase;letter-spacing:.12em;color:rgba(225,242,243,.45)}.tripGrid input{width:100%;min-width:0;height:43px;border:1px solid rgba(255,255,255,.065);outline:none;border-radius:10px;background:rgba(255,255,255,.045);color:#fff;padding:0 11px;font:inherit;font-size:11px;color-scheme:dark}.tripGrid input:focus{border-color:rgba(84,242,239,.42)}.money{display:flex;align-items:center;gap:6px}.money b{font-size:22px;color:var(--cyan)}
.setupActions{display:flex;justify-content:space-between;gap:12px;margin-top:17px}.primary,.secondary{min-height:47px;border-radius:12px;padding:12px 18px;font-size:10px;font-weight:850;cursor:pointer}.primary{display:flex;align-items:center;gap:16px;border:1px solid rgba(132,255,252,.56);background:var(--cyan);color:#001115}.primary span{font-size:14px}.secondary{border:1px solid rgba(255,255,255,.1);background:rgba(5,26,33,.55);color:rgba(239,250,250,.76);backdrop-filter:blur(14px)}
.orbit{position:relative;width:92px;height:92px;display:grid;place-items:center;border:1px solid rgba(84,242,239,.32);border-radius:24px;margin-bottom:27px;background:rgba(8,36,42,.3);box-shadow:inset 0 0 40px rgba(84,242,239,.045)}.orbit:before,.orbit:after{content:"";position:absolute;border:1px solid rgba(84,242,239,.13);border-radius:50%;inset:-12px}.orbit:after{inset:-24px;opacity:.55}.orbit span{font-size:27px;color:var(--cyan)}.orbit i{position:absolute;right:7px;top:8px;width:8px;height:8px;border-radius:50%;background:#fff;box-shadow:0 0 15px var(--cyan);animation:pulse 1.5s ease-in-out infinite}.thinking>p:last-child{max-width:760px;color:rgba(229,244,245,.52);line-height:1.55;font-size:11px}.thinkingSteps{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin:27px 0 17px}.thinkingSteps span{padding:8px 10px;border:1px solid rgba(84,242,239,.13);border-radius:8px;background:rgba(84,242,239,.04);font-size:8px;font-weight:800;letter-spacing:.04em;color:rgba(219,254,253,.7)}.thinkingSteps i{font-style:normal;color:rgba(84,242,239,.32)}

.resultsTop{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:20px}.resultsTop p:last-child{max-width:760px;margin:11px 0 0;color:rgba(228,243,244,.52);font-size:11px;line-height:1.55}.resultGrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.resultCard{position:relative;overflow:hidden;border:1px solid rgba(255,255,255,.1);border-radius:20px;background:rgba(3,18,24,.86);backdrop-filter:blur(22px);transition:.22s ease;box-shadow:0 20px 55px rgba(0,0,0,.18)}.resultCard:hover,.resultCard.active{transform:translateY(-5px);border-color:rgba(84,242,239,.4);box-shadow:0 30px 80px rgba(0,0,0,.34),0 0 0 1px rgba(84,242,239,.05)}.resultCard.active:before{content:"BEST MATCH";position:absolute;z-index:5;left:14px;top:14px;padding:6px 8px;border-radius:7px;background:var(--cyan);color:#001013;font-size:7px;font-weight:950;letter-spacing:.12em}.photo{height:225px;background:linear-gradient(145deg,#10323c,#06161c);background-size:cover;background-position:center;display:flex;justify-content:space-between;align-items:flex-start;padding:13px}.photo:after{content:"";position:absolute;left:0;right:0;top:0;height:225px;pointer-events:none;background:linear-gradient(0deg,rgba(2,12,16,.72),transparent 60%)}.photo span,.photo b{position:relative;z-index:2;padding:7px 9px;border:1px solid rgba(255,255,255,.08);border-radius:8px;background:rgba(2,13,18,.68);backdrop-filter:blur(11px);font-size:8px}.resultCard.active .photo span{opacity:0}.photo b{color:var(--cyan)}.cardBody{padding:18px}.cardBody>small{font-size:8px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:rgba(84,242,239,.67)}.cardBody h2{margin:8px 0 9px;font-size:31px;line-height:1;font-weight:820;letter-spacing:-.045em}.cardBody>p{min-height:65px;margin:0;color:rgba(230,244,245,.61);font-size:11px;line-height:1.55}.stayLine{display:flex;align-items:end;justify-content:space-between;gap:10px;margin:16px 0;padding-top:14px;border-top:1px solid rgba(255,255,255,.075)}.stayLine div{display:flex;flex-direction:column;gap:4px;min-width:0}.stayLine span{font-size:7px;font-weight:800;text-transform:uppercase;letter-spacing:.12em;color:rgba(229,243,244,.37)}.stayLine strong{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:10px}.stayLine>b{color:var(--cyan);white-space:nowrap;font-size:10px}.cardBody>a{display:flex;align-items:center;justify-content:space-between;text-decoration:none;color:#fff;font-weight:850;font-size:10px}.cardBody>a span{display:grid;place-items:center;width:27px;height:27px;border-radius:8px;background:rgba(84,242,239,.08);color:var(--cyan)}

button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid var(--cyan);outline-offset:3px}
@media(max-width:1150px){.nav{grid-template-columns:1fr auto}.navLinks{display:none}.landingGrid{grid-template-columns:minmax(0,1fr) 390px;gap:34px}.capabilities{grid-template-columns:repeat(2,1fr)}.capabilities>div:nth-child(2){border-right:0}.capabilities>div:nth-child(-n+2){border-bottom:1px solid rgba(255,255,255,.065)}.tripGrid{grid-template-columns:repeat(2,minmax(0,1fr))}.resultGrid{grid-template-columns:1fr}.resultCard{display:grid;grid-template-columns:300px 1fr}.photo{height:100%;min-height:230px}.photo:after{height:100%;width:300px}.cardBody>p{min-height:auto}}
@media(max-width:860px){.stage{align-items:flex-start;padding-top:30px}.landingGrid{grid-template-columns:1fr}.plannerCard{min-height:410px}.capabilities{margin-top:0}.heroPanel h1{font-size:clamp(46px,9vw,72px)}.plannerCard{order:3}.capabilities{order:2}.choiceGrid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:650px){.nav{height:64px;padding:0 15px}.brand small{display:none}.brand b{font-size:18px}.brandMark{width:34px;height:34px}.status span{display:none}.status{padding:8px}.langSwitch{min-width:37px}.stage{min-height:calc(100svh - 64px);padding:25px 15px 42px}.landingGrid{gap:20px}.releaseTag{margin-bottom:12px}.heroPanel h1{font-size:44px;line-height:1}.lead{margin:15px 0 20px;font-size:14px}.composer{grid-template-columns:1fr;grid-template-areas:"head" "input" "button";gap:8px;padding:13px;border-radius:17px}.composer textarea{min-height:82px}.composer button{min-height:51px;width:100%}.ideaRow{display:grid;grid-template-columns:1fr}.ideaRow button{justify-content:space-between;border-radius:11px}.trust{gap:11px}.plannerCard{min-height:385px;padding:18px;border-radius:19px}.plannerTop h2{font-size:23px}.mediaFan{height:150px;margin:24px 0 19px}.mediaTile{height:135px}.reasonFlow{grid-template-columns:1fr 1fr 1fr}.reasonFlow>i{display:none}.reasonFlow small{white-space:normal}.plannerFoot{margin-top:12px}.capabilities{grid-template-columns:1fr}.capabilities>div{border-right:0!important;border-bottom:1px solid rgba(255,255,255,.065)!important}.capabilities>div:last-child{border-bottom:0!important}.questionPanel,.setupPanel,.thinking{padding:22px 17px;border-radius:19px}.questionPanel h1,.setupPanel h1,.thinking h1{font-size:40px}.choiceGrid,.tripGrid{grid-template-columns:1fr}.setupActions,.resultsTop{align-items:stretch;flex-direction:column}.primary,.secondary{width:100%;justify-content:center}.thinkingSteps i{display:none}.thinkingSteps{display:grid;grid-template-columns:1fr 1fr}.resultCard{display:block}.photo{height:205px;min-height:0}.photo:after{height:205px;width:100%}.resultsTop h1{font-size:39px}.cardBody h2{font-size:29px}}
@media(prefers-reduced-motion:reduce){.backdrop,.aurora,.orbit i,.landingGrid,.heroPanel,.questionPanel,.setupPanel,.thinking,.results{animation:none!important;transition:none!important}}

"use client";

import { FormEvent,useEffect,useMemo,useState } from "react";
import styles from "./v40-discovery-experience.module.css";

type Lang="el"|"en";
type Traveler="solo"|"couple"|"family"|"friends";
type Mood="relax"|"romantic"|"food"|"warmth"|"city"|"nature"|"adventure"|"culture";
type QuestionId="companions"|"outcome"|"social"|"novelty"|"must_have"|"friction";
type Answer={questionId:QuestionId;value:string};
type Profile={travelerType:Traveler;moods:Mood[];pace:"slow"|"balanced"|"full";desiredEnergy:"restore"|"balanced"|"stimulating";socialPreference:"quiet"|"balanced"|"lively";noveltyPreference:"familiar"|"balanced"|"surprise";avoid:"long-travel"|"high-cost"|"crowds"|"none";mustHave:"sea"|"nature"|"culture"|"nightlife"|"none";dnaLabels:string[]};
type Discovery={summary:string;profile:Profile;answered:QuestionId[];nextQuestionId:QuestionId|null;confidence:number;complete:boolean};
type Media={imageUrl:string;sourceUrl:string;title:string;description?:string;license:string;attribution:string};
type Solution={rank:number;score:number;destination:{slug:string;name:string;nameEn:string;tags:string[]};stay:{sourceProductId:string;propertyName:string;trackingUrl:string;imageUrl:string|null;price:number|null;currency:string|null;distanceKm:number|null;availability:string|null;semanticScore:number;valueScore:number};matchedSignals:string[];reason:string};
type SolveResult={ok:boolean;version:number;intentSource:string;intentSummary:string;inventoryChecked:number;solutionCount:number;solutions:Solution[]};
type Phase="welcome"|"clarify"|"setup"|"thinking"|"results";

const DAY=86_400_000;
const say=(l:Lang,el:string,en:string)=>l==="el"?el:en;
const iso=(d:Date)=>d.toISOString().slice(0,10);
function nextFriday(){const now=new Date(),d=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate())),delta=(5-d.getUTCDay()+7)%7||7;return new Date(d.getTime()+delta*DAY)}

const questionCopy:Record<QuestionId,{el:string;en:string;choices:{v:string;el:string;en:string}[]}>= {
 companions:{el:"Με ποιον ταξιδεύεις;",en:"Who are you travelling with?",choices:[{v:"solo",el:"Μόνος/η",en:"Solo"},{v:"couple",el:"Ζευγάρι",en:"Couple"},{v:"family",el:"Οικογένεια",en:"Family"},{v:"friends",el:"Φίλοι",en:"Friends"}]},
 outcome:{el:"Τι θέλεις να σου αφήσει αυτό το ταξίδι;",en:"What should this trip give you?",choices:[{v:"rest reset quiet",el:"Ξεκούραση",en:"Reset"},{v:"reconnect romantic",el:"Σύνδεση",en:"Reconnect"},{v:"stimulating adventure energy",el:"Ενέργεια",en:"Energy"},{v:"culture inspiration",el:"Έμπνευση",en:"Inspiration"}]},
 social:{el:"Πόσο ζωντανά το θέλεις;",en:"How lively should it feel?",choices:[{v:"quiet",el:"Ήσυχα",en:"Quiet"},{v:"balanced",el:"Ισορροπημένα",en:"Balanced"},{v:"lively nightlife",el:"Ζωντανά",en:"Lively"}]},
 novelty:{el:"Να μείνω στα σίγουρα ή να σε εκπλήξω;",en:"Familiar or surprising?",choices:[{v:"familiar",el:"Σίγουρα",en:"Familiar"},{v:"balanced",el:"Ισορροπία",en:"Balanced"},{v:"surprise different",el:"Έκπληξέ με",en:"Surprise me"}]},
 must_have:{el:"Έχεις ένα πραγματικό must-have;",en:"One real must-have?",choices:[{v:"sea beach",el:"Θάλασσα",en:"Sea"},{v:"nature mountain",el:"Φύση",en:"Nature"},{v:"culture history",el:"Πολιτισμός",en:"Culture"},{v:"nightlife",el:"Βραδινή ζωή",en:"Nightlife"},{v:"none",el:"Όχι",en:"None"}]},
 friction:{el:"Τι θέλεις οπωσδήποτε να αποφύγεις;",en:"What do you want to avoid?",choices:[{v:"short easy no long travel",el:"Ταλαιπωρία",en:"Travel friction"},{v:"budget cheap",el:"Υψηλό κόστος",en:"High cost"},{v:"avoid crowds",el:"Πολυκοσμία",en:"Crowds"},{v:"none",el:"Τίποτα",en:"Nothing"}]}
};

export function V40DiscoveryExperience({lang="el"}:{lang?:Lang}){
 const friday=useMemo(()=>nextFriday(),[]);
 const[phase,setPhase]=useState<Phase>("welcome");
 const[need,setNeed]=useState("");
 const[answers,setAnswers]=useState<Answer[]>([]);
 const[profile,setProfile]=useState<Profile|null>(null);
 const[summary,setSummary]=useState("");
 const[nextQuestion,setNextQuestion]=useState<QuestionId|null>(null);
 const[start,setStart]=useState(iso(friday));
 const[end,setEnd]=useState(iso(new Date(friday.getTime()+3*DAY)));
 const[budget,setBudget]=useState(900);
 const[origin,setOrigin]=useState(say(lang,"Αθήνα","Athens"));
 const[traveler,setTraveler]=useState<Traveler>("couple");
 const[busy,setBusy]=useState(false);
 const[error,setError]=useState<string|null>(null);
 const[result,setResult]=useState<SolveResult|null>(null);
 const[activeIndex,setActiveIndex]=useState(0);
 const[heroMedia,setHeroMedia]=useState<Media[]>([]);
 const[frame,setFrame]=useState(0);
 const solutions=result?.solutions.slice(0,3)??[];
 const active=solutions[activeIndex]??solutions[0]??null;
 const background=active?.stay.imageUrl||heroMedia[frame%Math.max(1,heroMedia.length)]?.imageUrl||"";
 const q=nextQuestion?questionCopy[nextQuestion]:null;
 const destinationHref=lang==="en"?"/en/destinations":"/proorismoi";
 const guidesHref=lang==="en"?"/en/guides":"/guides";
 const howHref=lang==="en"?"/en/how-ai-works":"/how-ai-works";
 const languageHref=lang==="en"?"/":"/en";
 const inspiration=[
  {label:say(lang,"Βόρειο σέλας","Northern lights"),value:say(lang,"Θέλω εντυπωσιακή φύση, βόρειο σέλας και κάτι που να νιώθω μια φορά στη ζωή μου","I want dramatic nature, northern lights and a once-in-a-lifetime feeling")},
  {label:say(lang,"Food weekend","Food weekend"),value:say(lang,"Θέλω ένα σύντομο ταξίδι με εξαιρετικό φαγητό, όμορφη πόλη και όσο γίνεται λιγότερη ταλαιπωρία","I want a short trip with excellent food, a beautiful city and as little travel friction as possible")},
  {label:say(lang,"Reset δίπλα στη φύση","Nature reset"),value:say(lang,"Χρειάζομαι ηρεμία, φύση, καλό ξενοδοχείο και πραγματικό reset χωρίς πολυκοσμία","I need calm, nature, a good hotel and a real reset without crowds")}
 ];

 useEffect(()=>{const id=window.setTimeout(()=>{fetch("/api/escape/media?destination=Greece&mode=aerial").then(r=>r.ok?r.json():null).then((p:{items?:Media[]}|null)=>{if(p?.items?.length)setHeroMedia(p.items.slice(0,4))}).catch(()=>null)},250);return()=>window.clearTimeout(id)},[]);
 useEffect(()=>{const id=window.setInterval(()=>setFrame(v=>v+1),9000);return()=>window.clearInterval(id)},[]);

 async function discover(nextAnswers=answers){
  const r=await fetch("/api/escape/discovery",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({locale:lang,initialText:need.trim(),answers:nextAnswers})});
  if(!r.ok)throw new Error("discovery");
  const data=await r.json() as Discovery;setProfile(data.profile);setSummary(data.summary);setNextQuestion(data.nextQuestionId);setTraveler(data.profile.travelerType);return data;
 }
 async function begin(e:FormEvent){e.preventDefault();if(need.trim().length<8){setError(say(lang,"Πες μου με μία πρόταση τι θέλεις να ζήσεις και τι θέλεις να αποφύγεις.","Tell me in one sentence what you want to experience and avoid."));return}setBusy(true);setError(null);try{const d=await discover();setPhase(d.complete||!d.nextQuestionId?"setup":"clarify")}catch{setError(say(lang,"Δεν κατάλαβα αρκετά. Γράψε το όπως θα το έλεγες σε έναν καλό travel agent.","I need a clearer brief. Write it as you would say it to a good travel agent."))}finally{setBusy(false)}}
 async function answer(value:string){if(!nextQuestion)return;const updated=[...answers.filter(a=>a.questionId!==nextQuestion),{questionId:nextQuestion,value}];setAnswers(updated);setBusy(true);try{const d=await discover(updated);if(updated.length>=2||d.complete||!d.nextQuestionId)setPhase("setup")}catch{setPhase("setup")}finally{setBusy(false)}}
 function quickWeekend(){const f=nextFriday();setStart(iso(f));setEnd(iso(new Date(f.getTime()+3*DAY)))}
 async function solve(){
  const learned=profile??(await discover());const p="profile" in learned?learned.profile:learned;if(!p)return;
  const nights=Math.max(1,Math.round((Date.parse(`${end}T00:00:00Z`)-Date.parse(`${start}T00:00:00Z`))/DAY));
  const trip={origin,startDate:start,endDate:end,month:"flexible",nights,budget,moods:p.moods,travelerType:traveler,language:lang,distancePreference:"any",pace:p.pace,hotelStyle:"any",avoid:p.avoid,entryMode:"idea",groupSize:traveler==="solo"?1:traveler==="couple"?2:4,desiredEnergy:p.desiredEnergy,socialPreference:p.socialPreference,noveltyPreference:p.noveltyPreference,mustHave:p.mustHave,dateFlexibility:"few-days",transportMode:"any",stayLocationPreference:"balanced",tripText:[need,summary].filter(Boolean).join(". ").slice(0,1200)};
  setPhase("thinking");setBusy(true);setError(null);
  try{const r=await fetch("/api/escape/solve-v42",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(trip)});if(!r.ok)throw new Error();const data=await r.json() as SolveResult;if(!data.solutions?.length)throw new Error();setResult(data);setActiveIndex(0);setPhase("results")}catch{setPhase("setup");setError(say(lang,"Δεν θα σε στείλω πάλι σε αδιέξοδο. Δεν βρήκα ασφαλή ακριβή λύση για αυτές τις ημερομηνίες — άλλαξε μόνο ημερομηνίες ή άνοιξε λίγο το budget και ξαναδοκίμασε.","I will not send you into a dead end. I found no safe exact match for these dates — adjust dates or widen budget slightly and rerun."))}finally{setBusy(false)}
 }
 function destinationUrl(s:Solution){return `${lang==="en"?"/en/destinations/":"/proorismoi/"}${s.destination.slug}?start=${start}&end=${end}&budget=${budget}&origin=${encodeURIComponent(origin)}`}

 return <main className={styles.shell} style={background?{"--hero":`url(${background})`} as React.CSSProperties:undefined}>
  <div className={styles.backdrop}/><div className={styles.aurora}/><div className={styles.vignette}/><div className={styles.grain}/>
  <header className={styles.nav}>
   <a className={styles.brand} href={lang==="en"?"/en":"/"}><span className={styles.brandMark}>✦</span><div><b>TravelAI</b><small>Plan smarter. Travel deeper.</small></div></a>
   <nav className={styles.navLinks} aria-label={say(lang,"Κύρια πλοήγηση","Main navigation")}><a href={destinationHref}>{say(lang,"Προορισμοί","Destinations")}</a><a href={guidesHref}>{say(lang,"Εμπειρίες","Experiences")}</a><a href={howHref}>{say(lang,"Πώς δουλεύει","How it works")}</a></nav>
   <div className={styles.navActions}><a className={styles.langSwitch} href={languageHref}>{lang==="en"?"EL":"EN"}</a><div className={styles.status}><i/><span>{phase==="results"?say(lang,"Matches ready","Matches ready"):"Travel Agent"}</span></div></div>
  </header>

  <section className={styles.stage}>
   {phase==="welcome"&&<div className={styles.landingGrid}>
    <div className={styles.heroPanel}>
     <div className={styles.releaseTag}><i/> AI POWERED TRAVEL EXPERIENCES</div>
     <h1>{say(lang,"Μεγαλύτερα ταξίδια. Πιο αληθινές εμπειρίες.","Bigger journeys. More real experiences.")}</h1>
     <p className={styles.lead}>{say(lang,"Η AI δεν ξεκινά από έναν προορισμό. Ξεκινά από εσένα — τι χρειάζεσαι τώρα, τι θέλεις να αποφύγεις και ποια πραγματική απόδραση αξίζει τον χρόνο και το budget σου.","AI does not start with a destination. It starts with you — what you need now, what you want to avoid, and which real escape deserves your time and budget.")}</p>
     <form className={styles.composer} onSubmit={begin}>
      <div className={styles.composerHead}><span>✦</span><div><b>{say(lang,"AI Trip Planner","AI Trip Planner")}</b><small>{say(lang,"Πες το φυσικά. Δεν χρειάζεται φόρμα.","Say it naturally. No form required.")}</small></div></div>
      <textarea autoFocus value={need} onChange={e=>setNeed(e.target.value)} placeholder={say(lang,"π.χ. Είμαστε κουρασμένοι, θέλουμε 3-4 μέρες με καλό φαγητό, ωραίο τοπίο και χωρίς πολλή ταλαιπωρία…","e.g. We are tired and want 3-4 days with great food, beautiful scenery and very little travel friction…")}/>
      <button disabled={busy}><span>{busy?say(lang,"Καταλαβαίνω…","Understanding…"):say(lang,"Σχεδίασε το ταξίδι μου","Plan my trip")}</span><b>↗</b></button>
     </form>
     {error&&<p className={styles.error}>{error}</p>}
     <div className={styles.ideaRow}>{inspiration.map(x=><button type="button" key={x.label} onClick={()=>setNeed(x.value)}>{x.label}<span>＋</span></button>)}</div>
     <div className={styles.trust}><span>{say(lang,"Semantic intent","Semantic intent")}</span><span>{say(lang,"Πραγματικό inventory","Real inventory")}</span><span>{say(lang,"Fit πάνω από δημοτικότητα","Fit over popularity")}</span></div>
    </div>

    <aside className={styles.plannerCard} aria-label={say(lang,"Πώς σκέφτεται το TravelAI","How TravelAI thinks")}>
     <div className={styles.plannerTop}><div><small>TRAVEL INTELLIGENCE</small><h2>{say(lang,"Από την ανάγκη σου σε ένα ταξίδι που στέκεται στην πραγματικότητα.","From your real need to a trip that survives reality.")}</h2></div><span className={styles.liveBadge}><i/> LIVE</span></div>
     <div className={styles.mediaFan}>
      {[0,1,2].map((index)=><div key={index} className={styles.mediaTile} style={heroMedia[index]?.imageUrl?{backgroundImage:`url(${heroMedia[index].imageUrl})`}:undefined}><span>{index===0?say(lang,"Αίσθηση","Feel"):index===1?say(lang,"Τόπος","Place"):say(lang,"Stay","Stay")}</span></div>)}
     </div>
     <div className={styles.reasonFlow}><div><span>01</span><b>{say(lang,"Καταλαβαίνει","Understands")}</b><small>{say(lang,"mood + constraints","mood + constraints")}</small></div><i>→</i><div><span>02</span><b>{say(lang,"Ταιριάζει","Matches")}</b><small>{say(lang,"destination + stay","destination + stay")}</small></div><i>→</i><div><span>03</span><b>{say(lang,"Εξηγεί","Explains")}</b><small>{say(lang,"fit + trade-offs","fit + trade-offs")}</small></div></div>
     <div className={styles.plannerFoot}><span>✦</span><p>{say(lang,"Δεν ανεβάζουμε έναν προορισμό επειδή πληρώνει περισσότερο. Το commercial signal δεν αποφασίζει το fit.","A destination does not rank higher because it pays more. Commercial signals do not decide fit.")}</p></div>
    </aside>

    <div className={styles.capabilities}>
     <div><span>◎</span><p><b>{say(lang,"AI προσαρμογή","AI personalization")}</b><small>{say(lang,"Με βάση το πραγματικό brief σου","Built around your actual brief")}</small></p></div>
     <div><span>◇</span><p><b>{say(lang,"Πραγματικά stays","Real stays")}</b><small>{say(lang,"Inventory πριν την τελική πρόταση","Inventory before the final match")}</small></p></div>
     <div><span>◉</span><p><b>{say(lang,"Εξηγήσιμο fit","Explainable fit")}</b><small>{say(lang,"Γιατί #1 και όχι απλώς τι","Why #1, not just what")}</small></p></div>
     <div><span>⌁</span><p><b>{say(lang,"Λιγότερη τριβή","Less friction")}</b><small>{say(lang,"Μία απόφαση τη φορά","One decision at a time")}</small></p></div>
    </div>
   </div>}

   {phase==="clarify"&&q&&<div className={styles.questionPanel}><div className={styles.agentCue}><span>✦</span><div><small>Travel Agent</small><p>{summary}</p></div></div><p className={styles.eyebrow}>{say(lang,"Μία ερώτηση ακόμη — μόνο επειδή αλλάζει την απόφαση","One more question — only because it changes the decision")}</p><h1>{say(lang,q.el,q.en)}</h1><div className={styles.choiceGrid}>{q.choices.map(c=><button key={c.v} disabled={busy} onClick={()=>answer(c.v)}>{say(lang,c.el,c.en)}<span>↗</span></button>)}</div><button className={styles.skip} onClick={()=>setPhase("setup")}>{say(lang,"Αρκετά — προχώρα","Enough — continue")}</button></div>}

   {phase==="setup"&&<div className={styles.setupPanel}><div className={styles.panelKicker}><span>✦</span><p><b>{say(lang,"ΤΟ ΜΟΝΟ ΠΡΑΚΤΙΚΟ ΒΗΜΑ","ONE PRACTICAL STEP")}</b><small>{say(lang,"Η AI έχει ήδη το intent. Χρειάζεται μόνο το πραγματικό πλαίσιο.","AI already has the intent. It only needs the real-world frame.")}</small></p></div><h1>{say(lang,"Βάλε τα όρια. Εγώ θα κάνω την έρευνα.","Set the boundaries. I will do the research.")}</h1><p className={styles.setupSummary}>{summary||need}</p><div className={styles.tripGrid}><label><span>{say(lang,"Από","From")}</span><input type="date" value={start} onChange={e=>setStart(e.target.value)}/></label><label><span>{say(lang,"Έως","To")}</span><input type="date" value={end} min={start} onChange={e=>setEnd(e.target.value)}/></label><label><span>{say(lang,"Συνολικό budget","Total budget")}</span><div className={styles.money}><b>€</b><input type="number" min="150" step="50" value={budget} onChange={e=>setBudget(Math.max(150,Number(e.target.value)||150))}/></div></label><label><span>{say(lang,"Αφετηρία","Origin")}</span><input type="text" value={origin} onChange={e=>setOrigin(e.target.value)} placeholder={say(lang,"Αθήνα ή ATH","Athens or ATH")}/></label></div><div className={styles.setupActions}><button className={styles.secondary} onClick={quickWeekend}>{say(lang,"Επόμενο τριήμερο","Next long weekend")}</button><button className={styles.primary} disabled={busy||!origin.trim()||Date.parse(end)<=Date.parse(start)} onClick={()=>void solve()}>{say(lang,"Βρες τις 3 καλύτερες αποδράσεις","Find the 3 best escapes")} <span>↗</span></button></div>{error&&<p className={styles.error}>{error}</p>}</div>}

   {phase==="thinking"&&<div className={styles.thinking}><div className={styles.orbit}><span>✦</span><i/></div><p className={styles.eyebrow}>AI + REAL INVENTORY</p><h1>{say(lang,"Δεν ψάχνω απλώς προορισμούς. Ψάχνω ποιο ταξίδι αξίζει για εσένα.","I am not just searching destinations. I am finding which trip is worth it for you.")}</h1><div className={styles.thinkingSteps}><span>{say(lang,"Semantic intent","Semantic intent")}</span><i>→</i><span>{say(lang,"Destination fit","Destination fit")}</span><i>→</i><span>{say(lang,"Real stay inventory","Real stay inventory")}</span><i>→</i><span>{say(lang,"Trade-off check","Trade-off check")}</span></div><p>{say(lang,"Ένα inventory fetch. Semantic intent. Destination fit. Value. Απόσταση. Χωρίς 50 διαδοχικά lookups.","One inventory fetch. Semantic intent. Destination fit. Value. Distance. No 50 sequential lookups.")}</p></div>}

   {phase==="results"&&result&&<div className={styles.results}><div className={styles.resultsTop}><div><p className={styles.eyebrow}>Destination reveal · V44</p><h1>{say(lang,"Τρεις λύσεις. Καμία τυχαία.","Three options. None random.")}</h1><p>{say(lang,`Έλεγξα ${result.inventoryChecked} πραγματικές προσφορές και κράτησα μόνο τις τρεις ισχυρότερες λύσεις για το brief σου.`,`I checked ${result.inventoryChecked} real offers and kept only the three strongest solutions for your brief.`)}</p></div><button className={styles.secondary} onClick={()=>setPhase("setup")}>{say(lang,"Άλλαξε πλαίσιο","Adjust")}</button></div><div className={styles.resultGrid}>{solutions.map((s,i)=><article key={s.destination.slug} className={`${styles.resultCard} ${i===activeIndex?styles.active:""}`} onMouseEnter={()=>setActiveIndex(i)}><div className={styles.photo} style={s.stay.imageUrl?{backgroundImage:`url(${s.stay.imageUrl})`}:undefined}><span>#{i+1}</span><b>{s.score}% fit</b></div><div className={styles.cardBody}><small>{s.matchedSignals.slice(0,3).join(" · ")||"AI semantic fit"}</small><h2>{s.destination.name}</h2><p>{s.reason}</p><div className={styles.stayLine}><div><span>{say(lang,"Πραγματικό stay","Real stay")}</span><strong>{s.stay.propertyName}</strong></div>{s.stay.price!=null&&<b>{s.stay.currency??"EUR"} {Math.round(s.stay.price)}</b>}</div><a href={destinationUrl(s)}>{say(lang,"Δες γιατί ταιριάζει","See why it fits")} <span>↗</span></a></div></article>)}</div></div>}
  </section>
  {/* Legacy regression reference only; active solver is /api/escape/solve-v42. Destination reveal remains bounded to 3. /api/escape/solve-v36/stream */}
 </main>
}

