type Parsed={positive?:Partial<Record<V8Dimension,number>>;negative?:Partial<Record<V8Dimension,number>>;priorities?:V8Dimension[];qualifiers?:Partial<V8SemanticIntent["qualifiers"]>;confidence?:number;summary?:string;rationale?:string[]};
const clamp=(v:number)=>Math.max(0,Math.min(1,v));
const blank=()=>Object.fromEntries(V8_DIMENSIONS.map(k=>[k,0])) as Record<V8Dimension,number>;
const normalizedFreeText=(value:string)=>value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-zα-ω0-9]+/gi," ").replace(/\s+/g," ").trim();
const has=(text:string,pattern:RegExp)=>pattern.test(text);
const emptyQualifiers=():V8SemanticIntent["qualifiers"]=>({avoidCrowds:0,easyAccess:0,slowRhythm:0,walkable:0,localCharacter:0});
const mapDimension=(value:unknown):V8Dimension|null=>typeof value==="string"&&(V8_DIMENSIONS as readonly string[]).includes(value)?value as V8Dimension:null;

function baseStructuredWeights(request:TripRequest){
 const w=blank();
 for(const mood of request.moods){const map:Record<string,V8Dimension>={romantic:"romantic",relax:"relax",food:"food",culture:"culture",city:"city",nature:"nature",adventure:"adventure",warmth:"warmth"};const d=map[mood];if(d)w[d]=1;}
 if(request.travelerType==="family")w.family=Math.max(w.family,.75);
 if(request.travelerType==="friends")w.nightlife=Math.max(w.nightlife,.35);
 if(request.avoid==="high-cost")w.value=Math.max(w.value,.4);
 if(request.distancePreference==="island")w.beach=Math.max(w.beach,.5);
 if(request.pace==="slow"){w.relax=Math.max(w.relax,.35);w.wellness=Math.max(w.wellness,.2);}
 if(request.pace==="full"){w.city=Math.max(w.city,.25);w.culture=Math.max(w.culture,.25);w.adventure=Math.max(w.adventure,.2);}
 if(request.desiredEnergy==="restore"){w.relax=Math.max(w.relax,.8);w.wellness=Math.max(w.wellness,.55);w.nature=Math.max(w.nature,.35);}
 if(request.desiredEnergy==="stimulating"){w.adventure=Math.max(w.adventure,.55);w.city=Math.max(w.city,.4);w.culture=Math.max(w.culture,.35);}
 if(request.socialPreference==="quiet"){w.relax=Math.max(w.relax,.55);w.nature=Math.max(w.nature,.35);}
 if(request.socialPreference==="lively"){w.city=Math.max(w.city,.55);w.nightlife=Math.max(w.nightlife,.65);}
 if(request.noveltyPreference==="surprise")w.adventure=Math.max(w.adventure,.45);
 if(request.mustHave==="sea")w.beach=Math.max(w.beach,.95);
 if(request.mustHave==="nature")w.nature=Math.max(w.nature,.95);
 if(request.mustHave==="culture")w.culture=Math.max(w.culture,.95);
 if(request.mustHave==="nightlife")w.nightlife=Math.max(w.nightlife,.95);
 if(request.nights<=4)w.short_break=Math.max(w.short_break,.55);
 const month=Number(request.startDate.slice(5,7));if(month===4||month===5||month===9||month===10||month===11)w.shoulder_season=Math.max(w.shoulder_season,.25);
 if(request.moods.includes("warmth"))w.beach=Math.max(w.beach,.45);
 return w;
}

export function deterministicSemanticIntentV18(raw:string):V8SemanticIntent{return deterministicSemanticIntentV19(raw);}

function semanticFromParsed(parsed:Parsed,fallback:V8SemanticIntent,source:V8SemanticIntent["source"]):V8SemanticIntent{
 const positive={...fallback.positive,...parsed.positive},negative={...fallback.negative,...parsed.negative},qualifiers={...fallback.qualifiers,...parsed.qualifiers};
 for(const d of V8_DIMENSIONS){if((negative[d]??0)>=.75&&(positive[d]??0)>.3)positive[d]=.3;}
 return{positive,negative,priorities:parsed.priorities?.length?parsed.priorities:fallback.priorities,qualifiers,confidence:clamp(parsed.confidence??.9),source,rationale:(parsed.rationale??[]).slice(0,5)};
}

function memoryBlockedByCurrentRequestV45(request:TripRequest,d:V8Dimension,negative?:Partial<Record<V8Dimension,number>>){
 const rejected=Math.max(0,Math.min(1,Number(negative?.[d]??0)));
 if(rejected>=.45)return true;
 if(d==="nightlife"&&(request.socialPreference==="quiet"||request.avoid==="crowds"))return true;
 if(d==="luxury"&&request.avoid==="high-cost")return true;
 return false;
}
function applyLearnedPreferencesV45(request:TripRequest,weights:Record<V8Dimension,number>,learned?:Partial<Record<V8Dimension,number>>,negative?:Partial<Record<V8Dimension,number>>){
 if(!learned)return weights;
 for(const d of V8_DIMENSIONS){
  const remembered=Math.max(0,Math.min(.35,Number(learned[d]??0)));
  if(!remembered||memoryBlockedByCurrentRequestV45(request,d,negative))continue;
  // Persistent memory is deliberately a small soft prior, never a hard override.
  weights[d]=Math.min(2,weights[d]+Math.min(.16,remembered*.45));
 }
 return weights;
}

function enforceCurrentHardConstraintsV45(request:TripRequest,weights:Record<V8Dimension,number>){
 if(request.mustHave==="sea")weights.beach=Math.max(weights.beach,.98);
 if(request.mustHave==="nature")weights.nature=Math.max(weights.nature,.98);
 if(request.mustHave==="culture")weights.culture=Math.max(weights.culture,.98);
 if(request.mustHave==="nightlife")weights.nightlife=Math.max(weights.nightlife,.98);
 return weights;
}

function reconcileWeights(request:TripRequest,semantic:V8SemanticIntent,learned?:Partial<Record<V8Dimension,number>>){
 const weights=baseStructuredWeights(request);
 for(const d of V8_DIMENSIONS){const p=clamp(semantic.positive[d]??0),n=clamp(semantic.negative[d]??0);if(p>0)weights[d]=Math.max(weights[d]*.7,p);if(n>0)weights[d]*=1-n*.92;}
 if(semantic.qualifiers.avoidCrowds>0)weights.relax=Math.max(weights.relax,.7*semantic.qualifiers.avoidCrowds);
 if(semantic.qualifiers.slowRhythm>0)weights.relax=Math.max(weights.relax,.82*semantic.qualifiers.slowRhythm);
 if(semantic.qualifiers.walkable>0){weights.city=Math.max(weights.city,.5*semantic.qualifiers.walkable);weights.culture=Math.max(weights.culture,.4*semantic.qualifiers.walkable);}
 if(semantic.qualifiers.localCharacter>0)weights.culture=Math.max(weights.culture,.72*semantic.qualifiers.localCharacter);
 if(semantic.qualifiers.easyAccess>0)weights.short_break=Math.max(weights.short_break,.65*semantic.qualifiers.easyAccess);
 // V21: priority must be stronger than a normal selected mood. V18/V19 used <=1 targets,
 // so a structured mood already at weight=1 made "food first" or "culture first" a no-op.
 semantic.priorities.slice(0,3).forEach((d,i)=>{if((semantic.positive[d]??0)>=.35)weights[d]=Math.max(weights[d],[1.75,1.4,1.2][i]);});
 return enforceCurrentHardConstraintsV45(request,applyLearnedPreferencesV45(request,weights,learned,semantic.negative));
}

export function structuredIntent(request:TripRequest,learned?:Partial<Record<V8Dimension,number>>):V8IntentProfile{
 const text=request.tripText?.trim();if(!text)return{weights:enforceCurrentHardConstraintsV45(request,applyLearnedPreferencesV45(request,baseStructuredWeights(request),learned)),source:"structured",summary:request.moods.join(" + ")};
 const semantic=deterministicSemanticIntentV18(text);return{weights:reconcileWeights(request,semantic,learned),source:"structured",summary:request.moods.join(" + "),interpretedText:text,semantic};
}

const tierSource=(tier:ModelTierV16):V8IntentProfile["source"]=>tier==="free"?"structured+free":tier==="openai"?"structured+openai":"structured+deepseek";

export async function interpretIntentV8(request:TripRequest,budget:LLMRequestBudgetV16=createLLMRequestBudgetV16(),learned?:Partial<Record<V8Dimension,number>>):Promise<V8IntentProfile>{
 const base=structuredIntent(request,learned),text=request.tripText?.trim();if(!text||text.length<3)return base;const fallback=base.semantic??deterministicSemanticIntentV18(text),normalized=normalizedFreeText(text),clauseCount=(normalized.match(/(?:,| και | and | αλλα | but | ομως | however | χωρις | without )/g)??[]).length,semanticConflict=V8_DIMENSIONS.some(d=>(fallback.positive[d]??0)>.25&&(fallback.negative[d]??0)>.25),complexTradeoff=semanticConflict||clauseCount>=3;
 const system=`You are the canonical semantic parser for a travel decision engine. Parse EVERY clause of the traveller's free text. Do not recommend destinations and do not invent facts. Separate desires from dislikes and exclusions. Preserve priority and trade-offs. "not X" must never become a positive X preference. Hard geography and accommodation constraints are enforced elsewhere. Dimensions: ${V8_DIMENSIONS.join(", ")}. Return JSON only with this schema: {"positive":{"dimension":0..1},"negative":{"dimension":0..1},"priorities":["dimension"],"qualifiers":{"avoidCrowds":0..1,"easyAccess":0..1,"slowRhythm":0..1,"walkable":0..1,"localCharacter":0..1},"confidence":0..1,"summary":"max 120 chars","rationale":["short clause interpretations"]}. Use a dimension only when supported by the user's words. If the user says sea nearby but not a beach holiday, keep beach positive low and beach negative meaningful. If the user says food first but no nightlife, food is a priority and nightlife is negative.`;
 const routed=await generateJsonWithRoutingV16<Parsed>({context:{task:"intent",text,deterministicConfidence:fallback.confidence,hardConstraintRisk:false,contradictorySignals:complexTradeoff,forceSemantic:true},budget,system,prompt:text,preference:"critical",validate(raw){
  const readMap=(input:unknown)=>{const out:Partial<Record<V8Dimension,number>>={};if(!input||typeof input!=="object"||Array.isArray(input))return out;for(const [k,v] of Object.entries(input as Record<string,unknown>)){const d=mapDimension(k),n=Number(v);if(d&&Number.isFinite(n))out[d]=clamp(n);}return out;};
  const positive=readMap(raw.positive),negative=readMap(raw.negative),priorities=Array.isArray(raw.priorities)?raw.priorities.map(mapDimension).filter((x):x is V8Dimension=>Boolean(x)).slice(0,5):[];
  const qRaw=raw.qualifiers&&typeof raw.qualifiers==="object"&&!Array.isArray(raw.qualifiers)?raw.qualifiers as Record<string,unknown>:{};const qualifiers:Partial<V8SemanticIntent["qualifiers"]>={};for(const key of ["avoidCrowds","easyAccess","slowRhythm","walkable","localCharacter"] as const){const n=Number(qRaw[key]);if(Number.isFinite(n))qualifiers[key]=clamp(n);}
  const confidence=Number(raw.confidence),rationale=Array.isArray(raw.rationale)?raw.rationale.filter((x):x is string=>typeof x==="string").slice(0,5):[];
  if(!Object.keys(positive).length&&!Object.keys(negative).length&&!priorities.length&&!Object.keys(qualifiers).length)return null;
  return{positive,negative,priorities,qualifiers,confidence:Number.isFinite(confidence)?clamp(confidence):.85,summary:typeof raw.summary==="string"?raw.summary.slice(0,120):undefined,rationale};
 }});
 const source=routed?tierSource(routed.tier):"structured",semantic=routed?semanticFromParsed(routed.value,fallback,source):fallback,weights=reconcileWeights(request,semantic,learned);
 return{weights,source,summary:routed?.value.summary??base.summary,interpretedText:text,semantic:{...semantic,source}};
}

import { createOpenAI } from "@ai-sdk/openai";
import { createOpenAICompatible } from "@ai-sdk/openai-compatible";
import { generateText, type LanguageModel } from "ai";

export type CouncilModelPreference = "creative" | "critical";
export type ModelTierV16="free"|"deepseek"|"openai";
export type SemanticTaskV16="intent"|"stay-constraints"|"research"|"council"|"verification";
export interface RoutingContextV16{task:SemanticTaskV16;text?:string|null;deterministicConfidence?:number;hardConstraintRisk?:boolean;contradictorySignals?:boolean;forceSemantic?:boolean;}
export interface RoutedModelV16{tier:ModelTierV16;model:LanguageModel;maxOutputTokens:number;timeoutMs:number;label:string;}
export interface LLMRequestBudgetV16{reserve:(route:RoutedModelV16,steps?:number)=>boolean;snapshot:()=>{freeCalls:number;paidCalls:number;openAICalls:number;reservedOutputTokens:number};}

const envNumber=(name:string,fallback:number,min:number,max:number)=>{const value=Number(process.env[name]);return Number.isFinite(value)?Math.max(min,Math.min(max,value)):fallback};
const clamp=(value:number)=>Math.max(0,Math.min(1,value));
function deepSeekModel():LanguageModel|null{const apiKey=process.env.DEEPSEEK_API_KEY;if(!apiKey)return null;const thinkingEnabled=process.env.DEEPSEEK_THINKING_ENABLED!=="false";const provider=createOpenAICompatible({name:"travel-reasoner",apiKey,baseURL:`${process.env.DEEPSEEK_BASE_URL||"https://api.deepseek.com"}`.replace(/\/$/,""),supportsStructuredOutputs:false,transformRequestBody:body=>({...body,thinking:{type:thinkingEnabled?"enabled":"disabled"},...(thinkingEnabled?{reasoning_effort:"high"}:{})})});return provider(process.env.DEEPSEEK_PRIMARY_MODEL||process.env.DEEPSEEK_COUNCIL_MODEL||"deepseek-v4-pro");}
function openAIModel():LanguageModel|null{const apiKey=process.env.OPENAI_API_KEY;if(!apiKey||process.env.OPENAI_ESCALATION_ENABLED==="false")return null;const provider=createOpenAI({apiKey});return provider(process.env.OPENAI_COUNCIL_MODEL||process.env.OPENAI_VERIFY_MODEL||"gpt-5-nano");}
function selfHostedModel():LanguageModel|null{const baseURL=process.env.SELF_HOSTED_AI_BASE_URL,model=process.env.SELF_HOSTED_AI_MODEL;if(!baseURL||!model)return null;const provider=createOpenAICompatible({name:"travel-local",apiKey:process.env.SELF_HOSTED_AI_API_KEY||"local",baseURL:baseURL.replace(/\/$/,""),supportsStructuredOutputs:false});return provider(model);}
function huggingFaceModel():LanguageModel|null{const apiKey=process.env.HF_TOKEN||process.env.HUGGINGFACE_API_KEY;if(!apiKey)return null;const provider=createOpenAICompatible({name:"travel-open-model",apiKey,baseURL:(process.env.HF_ROUTER_BASE_URL||"https://router.huggingface.co/v1").replace(/\/$/,""),supportsStructuredOutputs:false});return provider(process.env.HF_FREE_MODEL||"Qwen/Qwen2.5-7B-Instruct-1M:cheapest");}

export function semanticRiskV16(context:RoutingContextV16){
 const text=(context.text??"").toLowerCase(),confidence=clamp(context.deterministicConfidence??.8);let risk=(1-confidence)*.58;
 if(context.hardConstraintRisk)risk+=.24;if(context.contradictorySignals)risk+=.18;
 if(/(?:μονο|χωρις|εκτος|οπωσδηποτε|\b(?:only|mono|without|except|must)\b)/.test(text))risk+=.12;
 if((text.match(/(?:,| και | and | αλλα | but | χωρις | without )/g)??[]).length>=3)risk+=.08;if(text.length>150)risk+=.06;if(/[a-z].*[α-ω]|[α-ω].*[a-z]/i.test(text))risk+=.05;return clamp(risk);
}

export function routingDecisionV16(context:RoutingContextV16){
 const risk=semanticRiskV16(context),deterministicThreshold=envNumber("LLM_DETERMINISTIC_CONFIDENCE_THRESHOLD",.93,.5,1),deepSeekThreshold=envNumber("LLM_DEEPSEEK_RISK_THRESHOLD",.68,.2,1),deepSeekConfidenceThreshold=envNumber("LLM_DEEPSEEK_CONFIDENCE_THRESHOLD",.55,.15,.9),openAIThreshold=envNumber("LLM_OPENAI_RISK_THRESHOLD",.9,.4,1),confidence=clamp(context.deterministicConfidence??.8),forced=context.forceSemantic===true;
 return{risk,useAnyModel:forced||confidence<deterministicThreshold||context.hardConstraintRisk===true||context.contradictorySignals===true,allowDeepSeek:risk>=deepSeekThreshold||context.hardConstraintRisk===true||context.contradictorySignals===true||confidence<deepSeekConfidenceThreshold,allowOpenAI:risk>=openAIThreshold&&(context.hardConstraintRisk===true||context.contradictorySignals===true)};
}
export function routedModelsV16(context:RoutingContextV16,preference:CouncilModelPreference="critical"):RoutedModelV16[]{
 const decision=routingDecisionV16(context);if(!decision.useAnyModel)return[];
 const freeMax=envNumber("FREE_LLM_MAX_OUTPUT_TOKENS",220,64,600),deepMax=envNumber("DEEPSEEK_MAX_OUTPUT_TOKENS",320,64,800),openMax=envNumber("OPENAI_MAX_OUTPUT_TOKENS",180,64,600);
 const free=[selfHostedModel(),huggingFaceModel()].filter((model):model is LanguageModel=>Boolean(model)).map((model,index)=>({tier:"free" as const,model,maxOutputTokens:freeMax,timeoutMs:envNumber("FREE_LLM_TIMEOUT_MS",6500,1000,20000),label:index===0?"self-hosted":"huggingface-open-model"}));
 const deep=decision.allowDeepSeek?deepSeekModel():null,open=decision.allowOpenAI?openAIModel():null;
 const deepRoute=deep?[{tier:"deepseek" as const,model:deep,maxOutputTokens:deepMax,timeoutMs:envNumber("DEEPSEEK_TIMEOUT_MS",9000,1000,25000),label:"deepseek"}]:[];
 const openRoute=open?[{tier:"openai" as const,model:open,maxOutputTokens:openMax,timeoutMs:envNumber("OPENAI_TIMEOUT_MS",6000,1000,15000),label:"openai"}]:[];
 void preference;return[...free,...deepRoute,...openRoute];
}
export function createLLMRequestBudgetV16():LLMRequestBudgetV16{const maxFree=envNumber("LLM_MAX_FREE_CALLS_PER_REQUEST",4,0,12),maxPaid=envNumber("LLM_MAX_PAID_CALLS_PER_REQUEST",2,0,6),maxOpenAI=envNumber("LLM_MAX_OPENAI_CALLS_PER_REQUEST",1,0,2),maxOutput=envNumber("LLM_MAX_RESERVED_OUTPUT_TOKENS_PER_REQUEST",1200,128,4000);let freeCalls=0,paidCalls=0,openAICalls=0,reservedOutputTokens=0;return{reserve(route,steps=1){const calls=Math.max(1,Math.min(3,steps)),tokens=route.maxOutputTokens*calls;if(reservedOutputTokens+tokens>maxOutput)return false;if(route.tier==="free"){if(freeCalls+calls>maxFree)return false;freeCalls+=calls;}else{if(paidCalls+calls>maxPaid)return false;if(route.tier==="openai"&&openAICalls+calls>maxOpenAI)return false;paidCalls+=calls;if(route.tier==="openai")openAICalls+=calls;}reservedOutputTokens+=tokens;return true;},snapshot:()=>({freeCalls,paidCalls,openAICalls,reservedOutputTokens})};}
function jsonObject(raw:string){const cleaned=raw.replace(/^```(?:json)?\s*/i,"").replace(/\s*```$/i,"").trim(),start=cleaned.indexOf("{"),end=cleaned.lastIndexOf("}");if(start<0||end<=start)return null;try{return JSON.parse(cleaned.slice(start,end+1)) as Record<string,unknown>}catch{return null}}
export async function generateJsonWithRoutingV16<T>(args:{context:RoutingContextV16;budget:LLMRequestBudgetV16;system:string;prompt:string;preference?:CouncilModelPreference;validate:(value:Record<string,unknown>)=>T|null}){const routes=routedModelsV16(args.context,args.preference??"critical");for(const route of routes){if(!args.budget.reserve(route,1))continue;const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),route.timeoutMs);try{const result=await generateText({model:route.model,system:args.system,prompt:args.prompt,maxOutputTokens:route.maxOutputTokens,temperature:0,maxRetries:0,abortSignal:controller.signal});const parsed=jsonObject(result.text),value=parsed?args.validate(parsed):null;if(value)return{value,tier:route.tier,label:route.label};}catch{}finally{clearTimeout(timer)}}return null;}
export function councilModels(preference:CouncilModelPreference,includeDeepSeek=true):LanguageModel[]{const context:RoutingContextV16={task:"council",deterministicConfidence:includeDeepSeek?.7:.88,hardConstraintRisk:includeDeepSeek};return routedModelsV16(context,preference).filter(route=>includeDeepSeek||route.tier==="free").map(route=>route.model);}
